// apps/fidget-cam/verilator/fidget_voxel_tb.cpp
//
// Verilator harness for `fidget_impeller_voxel_cam`, the voxel evaluator the Lean compiler emits
// from the fidget part's F-Rep tape (`Obend.Apps.FidgetCam.fidgetImpellerVoxelCamRtlModule`,
// regenerated by `obend-emit-sv fidget`). It holds no copy of the geometry: the part is whatever
// the RTL says is solid, and the tool path is the program Lean posted (`obend-emit-sv fidget-ngc`,
// `Obend.Apps.FidgetCam.impeller5AxisNgc`), read from the path given as argv[1].
//
// What it does, in order:
//   1. scans the part's lattice box through the RTL (`out_in_solid_3d`) into a voxel map, and checks
//      the module's own counters against the scan;
//   2. writes the exposed voxel faces as a binary STL (argv[2]);
//   3. parses the posted program, re-checks that rotary moves happen only on rapids at the clearance
//      plane (the theorem is `Kinematics.postMoves_rotarySafe`), and re-checks every posted waypoint
//      against every solid voxel the cutter ball could touch (`out_no_gouge_ok`); the proof over
//      every lattice point of every segment is `FidgetCam.fidget_toolpath_no_gouge`, this is a
//      re-check of the waypoints on the emitted hardware;
//   4. places the tip on a solid voxel and checks the gouge counter trips.
//
// Units: the program is millimetres (G21); the lattice is `fidgetParams.unit` = 100 µm, so every
// coordinate times ten must be an integer, which is checked. The two numbers below are the only
// part parameters this file carries, both named after their Lean definitions.

#include "Vfidget_impeller_voxel_cam.h"
#include "verilated.h"
#include "verilated_vcd_c.h"

#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <tuple>
#include <vector>

namespace {

// `fidgetParams.unit` (µm per lattice step) and `fidgetParams.lat fidgetParams.toolR` (ball radius in
// lattice steps). The RTL bakes the radius in; the harness needs it only to place the ball centre
// of a tilted cutter (`frepBallEndMill`: centre = tip + r·u/n) where the RTL expects a vertical tip.
constexpr int64_t kUnitUm = 100;
constexpr int64_t kToolRLat = 20;

// The lattice box scanned: `fidgetParams.partBox` (hull of the hub and lug cylinders), lattice units.
constexpr int X_MIN = -100, X_MAX = 125;
constexpr int Y_MIN = -100, Y_MAX = 100;
constexpr int Z_MIN = 0,    Z_MAX = 80;
constexpr int NX = X_MAX - X_MIN + 1;
constexpr int NY = Y_MAX - Y_MIN + 1;
constexpr int NZ = Z_MAX - Z_MIN + 1;

#pragma pack(push, 1)
struct StlTriangle {
    float normal[3];
    float v0[3];
    float v1[3];
    float v2[3];
    uint16_t attribute;
};
#pragma pack(pop)
static_assert(sizeof(StlTriangle) == 50, "binary STL facet is 50 bytes");

void addQuadAsTriangles(std::vector<StlTriangle>& tris, float nx, float ny, float nz,
                        float ax, float ay, float az, float bx, float by, float bz,
                        float cx, float cy, float cz, float dx, float dy, float dz) {
    StlTriangle t1{};
    t1.normal[0] = nx; t1.normal[1] = ny; t1.normal[2] = nz;
    t1.v0[0] = ax; t1.v0[1] = ay; t1.v0[2] = az;
    t1.v1[0] = bx; t1.v1[1] = by; t1.v1[2] = bz;
    t1.v2[0] = cx; t1.v2[1] = cy; t1.v2[2] = cz;
    StlTriangle t2{};
    t2.normal[0] = nx; t2.normal[1] = ny; t2.normal[2] = nz;
    t2.v0[0] = ax; t2.v0[1] = ay; t2.v0[2] = az;
    t2.v1[0] = cx; t2.v1[1] = cy; t2.v1[2] = cz;
    t2.v2[0] = dx; t2.v2[1] = dy; t2.v2[2] = dz;
    tris.push_back(t1);
    tris.push_back(t2);
}

// One motion block of the posted program: tip in lattice units, A/C in degrees, rapid or feed.
struct NcBlock {
    bool rapid;
    int64_t x, y, z;
    double a, c;
    int line;
};

// `12.345` mm -> lattice steps; refuses anything that is not a whole number of steps.
int64_t mmToLat(const std::string& tok, int line) {
    double mm = std::stod(tok);
    double steps = mm * 1000.0 / static_cast<double>(kUnitUm);
    double r = std::llround(steps);
    if (std::fabs(steps - r) > 1e-6) {
        std::cerr << "line " << line << ": coordinate " << tok << " mm is not on the " << kUnitUm
                  << " um lattice\n";
        std::exit(2);
    }
    return static_cast<int64_t>(r);
}

std::vector<NcBlock> parseNgc(const std::string& path) {
    std::ifstream in(path);
    if (!in.is_open()) {
        std::cerr << "cannot open posted program " << path << " (run `obend-emit-sv fidget-ngc`)\n";
        std::exit(2);
    }
    std::vector<NcBlock> blocks;
    std::string ln;
    int lineNo = 0;
    bool sawTcpm = false;
    while (std::getline(in, ln)) {
        ++lineNo;
        if (ln.rfind("G43.4", 0) == 0) sawTcpm = true;
        if (ln.rfind("G00 ", 0) != 0 && ln.rfind("G01 ", 0) != 0) continue;
        NcBlock b{};
        b.rapid = ln.rfind("G00", 0) == 0;
        b.line = lineNo;
        bool hx = false, hy = false, hz = false, ha = false, hc = false;
        std::istringstream ss(ln.substr(4));
        std::string tok;
        while (ss >> tok) {
            char w = tok[0];
            std::string v = tok.substr(1);
            switch (w) {
                case 'X': b.x = mmToLat(v, lineNo); hx = true; break;
                case 'Y': b.y = mmToLat(v, lineNo); hy = true; break;
                case 'Z': b.z = mmToLat(v, lineNo); hz = true; break;
                case 'A': b.a = std::stod(v); ha = true; break;
                case 'C': b.c = std::stod(v); hc = true; break;
                case 'F': break;
                default:
                    std::cerr << "line " << lineNo << ": unexpected word " << tok << "\n";
                    std::exit(2);
            }
        }
        assert(hx && hy && hz && ha && hc && "every posted block carries X Y Z A C");
        blocks.push_back(b);
    }
    assert(sawTcpm && "the post turns TCPM on (G43.4) before the first move");
    return blocks;
}

// Ball centre of a cutter whose tip is at `b` on the axis the A/C angles describe
// (A the tilt from +Z, C the azimuth from +X): tip + r * (sinA cosC, sinA sinC, cosA).
std::tuple<int64_t, int64_t, int64_t> ballCentre(const NcBlock& b) {
    const double kPi = 3.14159265358979323846;
    double a = b.a * kPi / 180.0;
    double c = b.c * kPi / 180.0;
    double ux = std::sin(a) * std::cos(c);
    double uy = std::sin(a) * std::sin(c);
    double uz = std::cos(a);
    auto rnd = [](double v) { return static_cast<int64_t>(std::llround(v)); };
    return {b.x + rnd(kToolRLat * ux), b.y + rnd(kToolRLat * uy), b.z + rnd(kToolRLat * uz)};
}

}  // namespace

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    Verilated::randReset(2);
    Verilated::traceEverOn(true);

    const std::string ngcPath = argc > 1 ? argv[1] : "../build/impeller_5axis.ngc";
    const std::string stlPath = argc > 2 ? argv[2] : "build/impeller_part.stl";

    auto* dut = new Vfidget_impeller_voxel_cam;
    auto* tfp = new VerilatedVcdC;
    dut->trace(tfp, 99);
    tfp->open("fidget_cam_trace.vcd");

    uint64_t sim_time = 0;
    uint64_t ticks = 0;
    auto tick = [&]() {
        dut->clk = 0;
        dut->eval();
        if (sim_time < 4096) tfp->dump(sim_time);
        sim_time++;
        dut->clk = 1;
        dut->eval();
        if (sim_time < 4096) tfp->dump(sim_time);
        sim_time++;
        ticks++;
    };
    auto setPoint = [&](int64_t x, int64_t y, int64_t z) {
        dut->in_x = static_cast<uint64_t>(x);
        dut->in_y = static_cast<uint64_t>(y);
        dut->in_z = static_cast<uint64_t>(z);
    };
    auto setTip = [&](int64_t tx, int64_t ty, int64_t tz) {
        dut->in_tx = static_cast<uint64_t>(tx);
        dut->in_ty = static_cast<uint64_t>(ty);
        dut->in_tz = static_cast<uint64_t>(tz);
    };

    // Reset; the tip parked far above the part so the gouge counter stays at zero during the scan.
    dut->rst = 1;
    setPoint(0, 0, 0);
    setTip(0, 0, 1000);
    tick();
    dut->rst = 0;
    ticks = 0;
    assert(dut->out_voxel_eval_cycles == 0ULL);
    assert(dut->out_solid_voxel_count == 0ULL);
    assert(dut->out_gouge_violations == 0ULL);

    // 1. The part, as the RTL evaluates it over the lattice box.
    std::vector<uint8_t> voxel_solid(static_cast<size_t>(NX) * NY * NZ, 0);
    auto idx3d = [&](int x, int y, int z) -> size_t {
        return static_cast<size_t>(((z - Z_MIN) * NY + (y - Y_MIN)) * NX + (x - X_MIN));
    };
    auto isSolidAt = [&](int64_t x, int64_t y, int64_t z) -> bool {
        if (x < X_MIN || x > X_MAX || y < Y_MIN || y > Y_MAX || z < Z_MIN || z > Z_MAX) return false;
        return voxel_solid[idx3d(static_cast<int>(x), static_cast<int>(y), static_cast<int>(z))] != 0;
    };
    uint64_t solid_voxels = 0;
    for (int z = Z_MIN; z <= Z_MAX; ++z) {
        for (int y = Y_MIN; y <= Y_MAX; ++y) {
            for (int x = X_MIN; x <= X_MAX; ++x) {
                setPoint(x, y, z);
                tick();
                // The full tape and the three box-compacted tapes agree inside their boxes
                // (`FidgetCam.compactFor_sound`); the boxes are the Lean constants.
                if (x >= 40 && x <= 60 && y >= -10 && y <= 10 && z >= 30 && z <= 50)
                    assert(dut->out_frep_center_pruned == dut->out_frep_full);
                if (x >= 112 && x <= 124 && y >= -5 && y <= 5 && z >= 30 && z <= 50)
                    assert(dut->out_frep_boss_pruned == dut->out_frep_full);
                if (x >= -50 && x <= -30 && y >= -8 && y <= 8 && z >= 30 && z <= 50)
                    assert(dut->out_frep_bore_pruned == dut->out_frep_full);
                if (dut->out_in_solid_3d != 0ULL) {
                    voxel_solid[idx3d(x, y, z)] = 1;
                    solid_voxels++;
                }
            }
        }
    }
    assert(dut->out_voxel_eval_cycles == ticks);
    assert(dut->out_solid_voxel_count == solid_voxels);
    assert(dut->out_gouge_violations == 0ULL);
    assert(solid_voxels > 0ULL);

    // 2. Exposed faces as a binary STL (lattice units; one unit is kUnitUm micrometres).
    std::vector<StlTriangle> triangles;
    uint64_t surface_voxels = 0;
    for (int z = Z_MIN; z <= Z_MAX; ++z) {
        for (int y = Y_MIN; y <= Y_MAX; ++y) {
            for (int x = X_MIN; x <= X_MAX; ++x) {
                if (!isSolidAt(x, y, z)) continue;
                bool boundary = false;
                float x0 = x - 0.5f, x1 = x + 0.5f;
                float y0 = y - 0.5f, y1 = y + 0.5f;
                float z0 = z - 0.5f, z1 = z + 0.5f;
                if (!isSolidAt(x + 1, y, z)) { addQuadAsTriangles(triangles,  1, 0, 0, x1, y0, z0, x1, y1, z0, x1, y1, z1, x1, y0, z1); boundary = true; }
                if (!isSolidAt(x - 1, y, z)) { addQuadAsTriangles(triangles, -1, 0, 0, x0, y1, z0, x0, y0, z0, x0, y0, z1, x0, y1, z1); boundary = true; }
                if (!isSolidAt(x, y + 1, z)) { addQuadAsTriangles(triangles,  0, 1, 0, x1, y1, z0, x0, y1, z0, x0, y1, z1, x1, y1, z1); boundary = true; }
                if (!isSolidAt(x, y - 1, z)) { addQuadAsTriangles(triangles,  0, -1, 0, x0, y0, z0, x1, y0, z0, x1, y0, z1, x0, y0, z1); boundary = true; }
                if (!isSolidAt(x, y, z + 1)) { addQuadAsTriangles(triangles,  0, 0, 1, x0, y0, z1, x1, y0, z1, x1, y1, z1, x0, y1, z1); boundary = true; }
                if (!isSolidAt(x, y, z - 1)) { addQuadAsTriangles(triangles,  0, 0, -1, x0, y1, z0, x1, y1, z0, x1, y0, z0, x0, y0, z0); boundary = true; }
                if (boundary) surface_voxels++;
            }
        }
    }
    assert(!triangles.empty());
    {
        std::ofstream stl(stlPath, std::ios::binary);
        assert(stl.is_open());
        char header[80];
        std::memset(header, 0, sizeof(header));
        std::snprintf(header, sizeof(header), "obend fidget-cam: faces of the RTL voxel scan, 1 unit = %lld um",
                      static_cast<long long>(kUnitUm));
        stl.write(header, 80);
        uint32_t n = static_cast<uint32_t>(triangles.size());
        stl.write(reinterpret_cast<const char*>(&n), sizeof(uint32_t));
        stl.write(reinterpret_cast<const char*>(triangles.data()),
                  static_cast<std::streamsize>(triangles.size() * sizeof(StlTriangle)));
    }

    // 3. The posted program.
    std::vector<NcBlock> blocks = parseNgc(ngcPath);
    assert(!blocks.empty());
    int64_t clearanceZ = INT64_MIN;
    for (const auto& b : blocks) clearanceZ = std::max(clearanceZ, b.z);
    assert(blocks.front().rapid && blocks.front().z == clearanceZ && "first motion is a rapid at clearance");
    // Rotary safety, re-checked on the text: the axis changes only between two rapids at clearance.
    uint64_t axis_changes = 0;
    for (size_t i = 1; i < blocks.size(); ++i) {
        const auto& p = blocks[i - 1];
        const auto& q = blocks[i];
        bool sameAxis = std::fabs(p.a - q.a) < 1e-9 && std::fabs(p.c - q.c) < 1e-9;
        if (!sameAxis) {
            assert(q.rapid && p.z >= clearanceZ && q.z >= clearanceZ && "axis change off the clearance plane");
            axis_changes++;
        }
    }
    assert(axis_changes > 0 && "the program has 3+2 passes");

    // Every waypoint: the ball (grown by one unit in the RTL) touches no solid voxel.
    const int64_t rg = kToolRLat + 1;
    uint64_t waypoint_checks = 0;
    uint64_t waypoints_in_box = 0;
    int64_t min_tool_sdf = INT64_MAX;
    for (const auto& b : blocks) {
        auto [cx, cy, cz] = ballCentre(b);
        // The RTL puts the ball centre at (in_tx, in_ty, in_tz + r): hand it the centre minus r in z.
        setTip(cx, cy, cz - kToolRLat);
        bool touched_box = false;
        for (int64_t z = std::max<int64_t>(Z_MIN, cz - rg); z <= std::min<int64_t>(Z_MAX, cz + rg); ++z) {
            for (int64_t y = std::max<int64_t>(Y_MIN, cy - rg); y <= std::min<int64_t>(Y_MAX, cy + rg); ++y) {
                for (int64_t x = std::max<int64_t>(X_MIN, cx - rg); x <= std::min<int64_t>(X_MAX, cx + rg); ++x) {
                    if (!isSolidAt(x, y, z)) continue;
                    touched_box = true;
                    setPoint(x, y, z);
                    tick();
                    waypoint_checks++;
                    if (dut->out_no_gouge_ok != 1ULL) {
                        std::cerr << "gouge: program line " << b.line << " tip (" << b.x << "," << b.y << "," << b.z
                                  << ") A" << b.a << " C" << b.c << " touches voxel (" << x << "," << y << "," << z << ")\n";
                        return 1;
                    }
                    int64_t sdf = static_cast<int64_t>(dut->out_tool_sdf);
                    min_tool_sdf = std::min(min_tool_sdf, sdf);
                }
            }
        }
        if (touched_box) waypoints_in_box++;
    }
    assert(dut->out_gouge_violations == 0ULL);
    assert(waypoints_in_box > 0 && "some cutting waypoints have material within the ball's box");
    assert(min_tool_sdf > 0);

    // 4. The counter trips when the tip is put on a solid voxel.
    int64_t sx = 0, sy = 0, sz = 0;
    bool found = false;
    for (int x = X_MIN; x <= X_MAX && !found; ++x)
        if (isSolidAt(x, 0, Z_MAX / 2)) { sx = x; sy = 0; sz = Z_MAX / 2; found = true; }
    assert(found);
    setTip(sx, sy, sz);
    setPoint(sx, sy, sz);
    tick();
    assert(dut->out_in_solid_3d == 1ULL);
    assert(dut->out_no_gouge_ok == 0ULL);
    assert(dut->out_gouge_violations == 1ULL);

    tfp->close();
    std::cout << "[fidget-cam] PASS"
              << " scan_voxels=" << static_cast<uint64_t>(NX) * NY * NZ
              << " solid_voxels=" << solid_voxels
              << " surface_voxels=" << surface_voxels
              << " stl_triangles=" << triangles.size()
              << " program_blocks=" << blocks.size()
              << " axis_changes=" << axis_changes
              << " waypoint_checks=" << waypoint_checks
              << " min_tool_sdf=" << min_tool_sdf
              << " adversarial_gouge_detected=" << dut->out_gouge_violations
              << " cycles=" << dut->out_voxel_eval_cycles << "\n";
    delete tfp;
    delete dut;
    return 0;
}
